//! Acceptance criterion 3: decision-for-decision parity with the real TS planner. Reads one or
//! more JSON-lines dumps produced by `tools/ts-trace/gen-planner-dump.mjs` (never generated by
//! this test itself -- see that script's own doc comment for exactly what it records and why each
//! case is independently teacher-forced) and replays each case through the ported `Planner` on
//! the `ts_adapter::SimWorld` (`ts-parity` feature) backend, comparing the decision and
//! `lastInfo` bit-for-bit against what the real TS planner produced.
//!
//! `#[ignore]`d: needs both the `ts-parity` feature and a locally-generated (uncommitted, per
//! `CLAUDE.md`) dump directory. Run:
//! ```text
//! node tools/ts-trace/gen-planner-dump.mjs --map ... --out ~/aiddnet/data/traces/planner/x.jsonl ...
//! DDAI_PLANNER_DUMP_DIR=~/aiddnet/data/traces/planner \
//!   cargo test -p ddai-planner --features ts-parity --release --test parity_planner -- --ignored --nocapture
//! ```

#![cfg(feature = "ts-parity")]

mod common;

use ddai_planner::config::PlannerConfig;
use ddai_planner::memory::FreezeMemory;
use ddai_planner::plan_world::{PlanCollision, PlanWorld};
use ddai_planner::planner::{PlanStep, Planner};
use ddai_planner::types::{PlayerInput, TeeState, blank_tee_state};
use ddai_planner::vmath::Vec2;
use serde::Deserialize;
use std::path::{Path, PathBuf};

fn bits_to_f64(s: &str) -> f64 {
    let bits = u64::from_str_radix(s, 16).expect("hex f64 bits");
    f64::from_bits(bits)
}

fn hex_encode(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push_str(&format!("{b:02x}"));
    }
    s
}

#[derive(Deserialize)]
struct TeeJson {
    id: i32,
    alive: bool,
    #[serde(rename = "posX")]
    pos_x: String,
    #[serde(rename = "posY")]
    pos_y: String,
    #[serde(rename = "velX")]
    vel_x: String,
    #[serde(rename = "velY")]
    vel_y: String,
    #[serde(rename = "hookState")]
    hook_state: i32,
    #[serde(rename = "hookPosX")]
    hook_pos_x: String,
    #[serde(rename = "hookPosY")]
    hook_pos_y: String,
    #[serde(rename = "hookDirX")]
    hook_dir_x: String,
    #[serde(rename = "hookDirY")]
    hook_dir_y: String,
    #[serde(rename = "hookedPlayer")]
    hooked_player: i32,
    jumped: i32,
    #[serde(rename = "jumpsLeft")]
    jumps_left: i32,
    direction: i32,
    angle: String,
    #[serde(rename = "activeWeapon")]
    active_weapon: i32,
    frozen: bool,
    #[serde(rename = "freezeTicksLeft")]
    freeze_ticks_left: i64,
    #[serde(rename = "attackTick")]
    attack_tick: i64,
    #[serde(rename = "hookTick")]
    hook_tick: Option<i64>,
    #[serde(rename = "jumpedTotal")]
    jumped_total: Option<i32>,
    #[serde(rename = "reloadTicks")]
    reload_ticks: Option<i64>,
    #[serde(rename = "frozenFor")]
    frozen_for: Option<i64>,
    #[serde(rename = "deepFrozen")]
    deep_frozen: Option<bool>,
    jumps: Option<i32>,
    #[serde(rename = "ddnetFlags")]
    ddnet_flags: Option<i32>,
    #[serde(rename = "sinceAttack")]
    since_attack: Option<i64>,
}

impl TeeJson {
    fn to_tee_state(&self) -> TeeState {
        TeeState {
            id: self.id,
            alive: self.alive,
            pos: Vec2 {
                x: bits_to_f64(&self.pos_x),
                y: bits_to_f64(&self.pos_y),
            },
            vel: Vec2 {
                x: bits_to_f64(&self.vel_x),
                y: bits_to_f64(&self.vel_y),
            },
            hook_state: self.hook_state,
            hook_pos: Vec2 {
                x: bits_to_f64(&self.hook_pos_x),
                y: bits_to_f64(&self.hook_pos_y),
            },
            hook_dir: Vec2 {
                x: bits_to_f64(&self.hook_dir_x),
                y: bits_to_f64(&self.hook_dir_y),
            },
            hooked_player: self.hooked_player,
            jumped: self.jumped,
            jumps_left: self.jumps_left,
            direction: self.direction,
            angle: bits_to_f64(&self.angle),
            active_weapon: self.active_weapon,
            frozen: self.frozen,
            freeze_ticks_left: self.freeze_ticks_left,
            attack_tick: self.attack_tick,
            hook_tick: self.hook_tick,
            jumped_total: self.jumped_total,
            reload_ticks: self.reload_ticks,
            frozen_for: self.frozen_for,
            deep_frozen: self.deep_frozen,
            jumps: self.jumps,
            ddnet_flags: self.ddnet_flags,
            since_attack: self.since_attack,
        }
    }
}

#[derive(Deserialize)]
struct InputJson {
    direction: i32,
    #[serde(rename = "targetX")]
    target_x: String,
    #[serde(rename = "targetY")]
    target_y: String,
    jump: i32,
    fire: i32,
    hook: i32,
    #[serde(rename = "playerFlags")]
    player_flags: i32,
    #[serde(rename = "wantedWeapon")]
    wanted_weapon: i32,
    #[serde(rename = "nextWeapon")]
    next_weapon: i32,
    #[serde(rename = "prevWeapon")]
    prev_weapon: i32,
}

impl InputJson {
    fn to_input(&self) -> PlayerInput {
        PlayerInput {
            direction: self.direction,
            target_x: bits_to_f64(&self.target_x),
            target_y: bits_to_f64(&self.target_y),
            jump: self.jump,
            fire: self.fire,
            hook: self.hook,
            player_flags: self.player_flags,
            wanted_weapon: self.wanted_weapon,
            next_weapon: self.next_weapon,
            prev_weapon: self.prev_weapon,
        }
    }
}

/// Review round 1, F4: the scenario `tools/ts-trace/gen-planner-dump.mjs --scenario full` (or
/// `baseline`, all-empty) attached to a case -- concrete, already-resolved values (never
/// recomputed here) so applying them is bit-for-bit what the TS side did.
#[derive(Deserialize)]
struct Vec2Json {
    #[serde(rename = "xBits")]
    x_bits: String,
    #[serde(rename = "yBits")]
    y_bits: String,
}
impl Vec2Json {
    fn to_vec2(&self) -> Vec2 {
        Vec2 {
            x: bits_to_f64(&self.x_bits),
            y: bits_to_f64(&self.y_bits),
        }
    }
}

#[derive(Deserialize)]
struct BystanderJson {
    #[serde(rename = "xBits")]
    x_bits: String,
    #[serde(rename = "yBits")]
    y_bits: String,
    #[serde(rename = "vxBits")]
    vx_bits: String,
    #[serde(rename = "vyBits")]
    vy_bits: String,
}

#[derive(Deserialize)]
struct BandJson {
    #[serde(rename = "x0Bits")]
    x0_bits: String,
    #[serde(rename = "y0Bits")]
    y0_bits: String,
    #[serde(rename = "x1Bits")]
    x1_bits: String,
    #[serde(rename = "y1Bits")]
    y1_bits: String,
}

#[derive(Deserialize)]
struct MemNoteJson {
    #[serde(rename = "xBits")]
    x_bits: String,
    #[serde(rename = "yBits")]
    y_bits: String,
    kind: String,
}

#[derive(Deserialize)]
struct ExtraTeeJson {
    id: i32,
    #[serde(rename = "xBits")]
    x_bits: String,
    #[serde(rename = "yBits")]
    y_bits: String,
    frozen: bool,
    #[serde(rename = "freezeTicksLeft")]
    freeze_ticks_left: i64,
}

#[derive(Deserialize)]
struct ScenarioJson {
    goal: Option<Vec2Json>,
    thirds: Vec<Vec2Json>,
    #[serde(rename = "frozenBystanders")]
    frozen_bystanders: Vec<BystanderJson>,
    #[serde(rename = "spareBystanders")]
    spare_bystanders: Vec<BystanderJson>,
    band: Option<BandJson>,
    #[serde(rename = "memoryNotes")]
    memory_notes: Vec<MemNoteJson>,
    overrides: Option<String>,
    #[serde(rename = "extraTees")]
    extra_tees: Vec<ExtraTeeJson>,
}

fn apply_scenario<W: PlanWorld>(planner: &mut Planner<W>, world: &mut W, sc: &ScenarioJson) {
    planner.set_travel_goal(sc.goal.as_ref().map(Vec2Json::to_vec2));
    planner.set_third_tees(sc.thirds.iter().map(Vec2Json::to_vec2).collect());
    planner.set_frozen_bystanders(
        sc.frozen_bystanders
            .iter()
            .map(|b| Vec2 {
                x: bits_to_f64(&b.x_bits),
                y: bits_to_f64(&b.y_bits),
            })
            .collect(),
        sc.frozen_bystanders
            .iter()
            .map(|b| Vec2 {
                x: bits_to_f64(&b.vx_bits),
                y: bits_to_f64(&b.vy_bits),
            })
            .collect(),
    );
    planner.set_spare_bystanders(
        sc.spare_bystanders
            .iter()
            .map(|b| Vec2 {
                x: bits_to_f64(&b.x_bits),
                y: bits_to_f64(&b.y_bits),
            })
            .collect(),
        sc.spare_bystanders
            .iter()
            .map(|b| Vec2 {
                x: bits_to_f64(&b.vx_bits),
                y: bits_to_f64(&b.vy_bits),
            })
            .collect(),
    );
    planner.set_band(sc.band.as_ref().map(|b| {
        (
            bits_to_f64(&b.x0_bits),
            bits_to_f64(&b.y0_bits),
            bits_to_f64(&b.x1_bits),
            bits_to_f64(&b.y1_bits),
        )
    }));
    if sc.memory_notes.is_empty() {
        planner.set_freeze_memory(None);
    } else {
        let col_w = world.collision().width();
        let col_h = world.collision().height();
        let mut mem = FreezeMemory::new(col_w, col_h);
        for n in &sc.memory_notes {
            let (x, y) = (bits_to_f64(&n.x_bits), bits_to_f64(&n.y_bits));
            if n.kind == "note" {
                mem.note(x, y);
            } else {
                mem.note_pass(x, y);
            }
        }
        planner.set_freeze_memory(Some(mem));
    }
    planner.set_overrides(match sc.overrides.as_deref() {
        Some("wb") => Some(Box::new(ddai_planner::config::wb_overrides) as Box<dyn Fn(PlannerConfig) -> PlannerConfig>),
        // af49dfb: the overrides a wayblock hall applies by role (`wbPlanOverrides`): the plain ones and the guard's plan per side.
        Some("wbv2") => Some(Box::new(ddai_planner::config::wb_overrides_v2)),
        Some("guardl") => Some(Box::new(|b| {
            ddai_planner::config::wb_guard_plan(ddai_planner::config::wb_overrides_v2(b), -1, false)
        })),
        Some("guardr") => Some(Box::new(|b| {
            ddai_planner::config::wb_guard_plan(ddai_planner::config::wb_overrides_v2(b), 1, false)
        })),
        Some("guardchain") => Some(Box::new(|b| {
            ddai_planner::config::wb_guard_plan(ddai_planner::config::wb_overrides_v2(b), -1, true)
        })),
        Some(other) => panic!("unknown scenario override {other}"),
        None => None,
    });
    for t in &sc.extra_tees {
        let pos = Vec2 {
            x: bits_to_f64(&t.x_bits),
            y: bits_to_f64(&t.y_bits),
        };
        if world.get_tee(t.id).is_none() {
            world.add_tee(t.id, pos);
        }
        let base = world.get_tee(t.id).unwrap_or_else(blank_tee_state);
        world.apply_tee_state(
            t.id,
            &TeeState {
                pos,
                vel: Vec2 { x: 0.0, y: 0.0 },
                frozen: t.frozen,
                freeze_ticks_left: t.freeze_ticks_left,
                ..base
            },
        );
    }
}

