fn classic_version() -> String {
    "classic".to_string()
}

#[derive(Deserialize)]
#[serde(tag = "kind", rename_all = "lowercase")]
// Test-only deserialization enum, one value per JSON line -- not a hot path, so the size gap
// between variants (`Meta` vs the data-heavy `Case`/`Decision`) is not worth boxing fields over.
#[allow(clippy::large_enum_variant)]
enum Line {
    Meta {
        #[serde(rename = "mapPath")]
        map_path: String,
        #[serde(rename = "mapSha256")]
        map_sha256: String,
        preset: String,
        opponent: String,
        /// `"classic"` (upstream c3c619d) when the dump has no such field (the first corpus), else the generator's reference.
        #[serde(rename = "plannerVersion", default = "classic_version")]
        planner_version: String,
    },
    Case {
        tick: i64,
        #[serde(rename = "self")]
        self_tee: TeeJson,
        enemy: TeeJson,
        #[serde(rename = "prevInput")]
        prev_input: InputJson,
        #[serde(rename = "enemyInput")]
        enemy_input: InputJson,
        scenario: ScenarioJson,
        decision: InputJson,
        #[serde(rename = "lastInfo")]
        last_info: LastInfoJson,
        #[serde(rename = "candidateLog")]
        candidate_log: Vec<CandidateJson>,
        hidden: HiddenJson,
    },
}

/// Review round 1, F11: an earlier revision skipped `player_flags`/`next_weapon`/`prev_weapon` --
/// harmless in practice today (the planner always writes `0` to all three, `stepToInput`/
/// `executedAim`'s `raw[...]` never touches them), but a silent gap in what this test actually
/// proves; comparing every field costs nothing and closes it for good.
fn input_eq_bits(a: &PlayerInput, b: &PlayerInput) -> bool {
    a.direction == b.direction
        && a.target_x.to_bits() == b.target_x.to_bits()
        && a.target_y.to_bits() == b.target_y.to_bits()
        && a.jump == b.jump
        && a.fire == b.fire
        && a.hook == b.hook
        && a.wanted_weapon == b.wanted_weapon
        && a.player_flags == b.player_flags
        && a.next_weapon == b.next_weapon
        && a.prev_weapon == b.prev_weapon
}

struct Mismatch {
    file: String,
    tick: i64,
    detail: String,
}

/// Replays every case in one dump file. Returns `(total, first_mismatch)`.
fn replay_file(path: &Path) -> (usize, Option<Mismatch>) {
    let text = std::fs::read_to_string(path).unwrap_or_else(|e| panic!("reading {}: {e}", path.display()));
    let mut map_path: Option<String> = None;
    let mut map_sha256: Option<String> = None;
    let mut cfg: Option<PlannerConfig> = None;
    let mut collision: Option<ddai_tsworld::Collision> = None;
    let mut total = 0usize;
    let mut first_mismatch: Option<Mismatch> = None;

    for line in text.lines() {
        if line.trim().is_empty() {
            continue;
        }
        let parsed: Line =
            serde_json::from_str(line).unwrap_or_else(|e| panic!("{}: bad json line: {e}\n{line}", path.display()));
        match parsed {
            Line::Meta {
                map_path: mp,
                map_sha256: sha,
                preset,
                opponent,
                planner_version,
            } => {
                let bytes = std::fs::read(&mp).unwrap_or_else(|e| panic!("reading map {mp}: {e}"));
                let actual_sha = {
                    use sha2::{Digest, Sha256};
                    let mut h = Sha256::new();
                    h.update(&bytes);
                    hex_encode(&h.finalize())
                };
                assert_eq!(actual_sha, sha, "map file changed since the dump was generated: {mp}");
                let loaded = ddai_tsworld::load_map_bytes(&bytes).unwrap_or_else(|e| panic!("loading map {mp}: {e:?}"));
                collision = Some(loaded.collision);
                cfg = Some(common::build_cfg(&planner_version, &preset, &opponent));
                map_path = Some(mp);
                map_sha256 = Some(sha);
            }
            Line::Case {
                tick,
                self_tee,
                enemy,
                prev_input,
                enemy_input,
                scenario,
                decision,
                last_info,
                candidate_log,
                hidden,
            } => {
                let cfg = cfg.expect("meta line must precede case lines");
                let collision = collision.as_ref().expect("meta line must precede case lines");
                total += 1;

                let mut planner: Planner<ddai_tsworld::SimWorld> = Planner::new(cfg);
                planner.reset();
                let mut world = ddai_tsworld::SimWorld::new(
                    collision.clone(),
                    ddai_tsworld::world::SimWorldOptions {
                        respawn_delay_ticks: Some(0),
                        infinite_ammo: Some(true),
                        sv_hit: Some(true),
                        all_weapons: None,
                        no_weak_hook: None,
                    },
                );
                let self_state = self_tee.to_tee_state();
                let enemy_state = enemy.to_tee_state();
                <ddai_tsworld::SimWorld as PlanWorld>::add_tee(&mut world, 0, self_state.pos);
                <ddai_tsworld::SimWorld as PlanWorld>::add_tee(&mut world, 1, enemy_state.pos);
                <ddai_tsworld::SimWorld as PlanWorld>::apply_tee_state(&mut world, 0, &self_state);
                <ddai_tsworld::SimWorld as PlanWorld>::apply_tee_state(&mut world, 1, &enemy_state);

                apply_scenario(&mut planner, &mut world, &scenario);
                planner.set_live_tick(<ddai_tsworld::SimWorld as PlanWorld>::tick(&world));

                planner.start_candidate_log();
                let got = planner.decide(&mut world, 0, 1, prev_input.to_input(), enemy_input.to_input());
                let got_candidates = planner.take_candidate_log();
                let want = decision.to_input();
                let li = planner.last_info;
                let got_hidden = planner.debug_state();

                if !input_eq_bits(&got, &want) {
                    first_mismatch.get_or_insert(Mismatch {
                        file: path.display().to_string(),
                        tick,
                        detail: format!(
                            "decision mismatch: got {got:?} want direction={} target=({:?},{:?}) jump={} fire={} hook={} wanted_weapon={}",
                            want.direction, want.target_x, want.target_y, want.jump, want.fire, want.hook, want.wanted_weapon
                        ),
                    });
                    continue;
                }
                let info_ok = li.searched == last_info.searched
                    && li.candidates == last_info.candidates
                    && li.out_of_time == last_info.out_of_time
                    && li.hook_at == last_info.hook_at
                    && li.gated == last_info.gated
                    && li.shielded == last_info.shielded
                    && li.edge_held == last_info.edge_held
                    && li.self_out == last_info.self_out
                    && li.enemy_out == last_info.enemy_out;
                if !info_ok {
                    first_mismatch.get_or_insert(Mismatch {
                        file: path.display().to_string(),
                        tick,
                        detail: format!(
                            "lastInfo mismatch: got candidates={} hookAt={} gated={} shielded={} edgeHeld={} selfOut={} enemyOut={} outOfTime={} searched={} want candidates={} hookAt={} gated={} shielded={} edgeHeld={} selfOut={} enemyOut={} outOfTime={} searched={}",
                            li.candidates, li.hook_at, li.gated, li.shielded, li.edge_held, li.self_out, li.enemy_out, li.out_of_time, li.searched,
                            last_info.candidates, last_info.hook_at, last_info.gated, last_info.shielded, last_info.edge_held, last_info.self_out, last_info.enemy_out, last_info.out_of_time, last_info.searched,
                        ),
                    });
                    continue;
                }

                // Review round 1, F4 acceptance: bit-exact (plan, score) for *every* candidate
                // this decision evaluated, not just the winner -- catches a score-perturbing
                // sabotage on the very first decision it touches, deterministically, regardless
                // of whether it happens to flip the final choice.
                if got_candidates.len() != candidate_log.len() {
                    first_mismatch.get_or_insert(Mismatch {
                        file: path.display().to_string(),
                        tick,
                        detail: format!(
                            "candidate count mismatch: got {} candidates, want {}",
                            got_candidates.len(),
                            candidate_log.len()
                        ),
                    });
                    continue;
                }
                let mut cand_mismatch: Option<String> = None;
                for (i, ((got_plan, got_score), want_c)) in got_candidates.iter().zip(candidate_log.iter()).enumerate()
                {
                    let want_plan: Vec<PlanStep> = want_c.plan.iter().map(PlanStepJson::to_plan_step).collect();
                    let want_score = bits_to_f64(&want_c.score_bits);
                    let plans_eq = got_plan.len() == want_plan.len()
                        && got_plan.iter().zip(want_plan.iter()).all(|(a, b)| {
                            a.dir == b.dir
                                && a.jump == b.jump
                                && a.hook == b.hook
                                && a.fire == b.fire
                                && a.aim.to_bits() == b.aim.to_bits()
                        });
                    if !plans_eq || got_score.to_bits() != want_score.to_bits() {
                        cand_mismatch = Some(format!(
                            "candidate #{i} mismatch: got plan={got_plan:?} score={got_score:?} (bits {:016x}) want plan={want_plan:?} score={want_score:?} (bits {:016x})",
                            got_score.to_bits(),
                            want_score.to_bits(),
                        ));
                        break;
                    }
                }
                if let Some(detail) = cand_mismatch {
                    first_mismatch.get_or_insert(Mismatch {
                        file: path.display().to_string(),
                        tick,
                        detail,
                    });
                    continue;
                }

                // Hidden cross-decision state (review round 1, F4: "dump ... RNG and hidden
                // state") -- proves the RNG was consumed exactly as many times, in the same way,
                // and every other piece of carried state (warm plan, committed input, dir
                // tracking, ...) ended up identical, not merely that the externally-visible
                // decision happened to match.
                let hid_ok = got_hidden.rng_s0 == hidden.rng_s0
                    && got_hidden.rng_s1 == hidden.rng_s1
                    && got_hidden.rng_s2 == hidden.rng_s2
                    && got_hidden.rng_s3 == hidden.rng_s3
                    && got_hidden.rng_have_spare == hidden.rng_have_spare
                    && got_hidden.rng_spare.to_bits() == bits_to_f64(&hidden.rng_spare_bits).to_bits()
                    && got_hidden.opp_seed == hidden.opp_seed
                    && got_hidden.commit_left == hidden.commit_left
                    && got_hidden.last_decide_tick == hidden.last_decide_tick
                    && got_hidden.decide_gaps == hidden.decide_gaps
                    && got_hidden.last_frozen == hidden.last_frozen
                    && got_hidden.dir_since == hidden.dir_since
                    && got_hidden.dir_last == hidden.dir_last;
                let warm_ok = match (&got_hidden.warm, &hidden.warm) {
                    (None, None) => true,
                    (Some(a), Some(b)) => {
                        a.len() == b.len()
                            && a.iter().zip(b.iter()).all(|(x, y)| {
                                let y = y.to_plan_step();
                                x.dir == y.dir
                                    && x.jump == y.jump
                                    && x.hook == y.hook
                                    && x.fire == y.fire
                                    && x.aim.to_bits() == y.aim.to_bits()
                            })
                    }
                    _ => false,
                };
                let committed_ok = match (&got_hidden.committed, &hidden.committed) {
                    (None, None) => true,
                    (Some(a), Some(b)) => input_eq_bits(a, &b.to_input()),
                    _ => false,
                };
                if !hid_ok || !warm_ok || !committed_ok {
                    first_mismatch.get_or_insert(Mismatch {
                        file: path.display().to_string(),
                        tick,
                        detail: format!(
                            "hidden-state mismatch: got {got_hidden:?} warm_ok={warm_ok} committed_ok={committed_ok}"
                        ),
                    });
                }
            }
        }
    }
    let _ = (map_path, map_sha256);
    (total, first_mismatch)
}

#[test]
#[ignore = "needs a locally-generated dump directory, see this file's doc comment"]
fn planner_matches_ts_across_the_dump_corpus() {
    let dir = std::env::var("DDAI_PLANNER_DUMP_DIR")
        .expect("set DDAI_PLANNER_DUMP_DIR to a directory of gen-planner-dump.mjs output");
    let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
        .unwrap_or_else(|e| panic!("reading {dir}: {e}"))
        .filter_map(|e| e.ok())
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|e| e == "jsonl"))
        .collect();
    files.sort();
    assert!(!files.is_empty(), "no .jsonl files in {dir}");

    let mut total = 0usize;
    let mut mismatches: Vec<Mismatch> = Vec::new();
    for f in &files {
        let (n, mism) = replay_file(f);
        total += n;
        if let Some(m) = mism {
            eprintln!("MISMATCH in {}: tick {} -- {}", m.file, m.tick, m.detail);
            mismatches.push(m);
        }
    }
    eprintln!(
        "replayed {total} decisions across {} files, {} files with a mismatch",
        files.len(),
        mismatches.len()
    );
    assert!(
        total >= 10_000,
        "acceptance criterion 3 wants >= 10k decisions, got {total}"
    );
    assert!(
        mismatches.is_empty(),
        "{} file(s) had a first mismatch -- see stderr above",
        mismatches.len()
    );
}
